68	     *  already has this many owners is rejected with 409 Conflict. */
69	    private static final int MAX_OWNERS_PER_CITY = 50;
70	
71	    /** Maximum number of owners that may be created on a single day (by registration date); creating
72	     *  an owner once this many owners already carry today's registration date is rejected with
73	     *  429 Too Many Requests. */
74	    private static final int MAX_OWNERS_PER_DAY = 100;
