138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
141	        HttpHeaders headers = new HttpHeaders();
142	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
143	        normalizeOwnerFields(owner);
144	        // Enforce the pre-persistence policies that can reject the new owner outright.
145	        rejectDisallowedOwnerCreation(owner);
146	        // Resolve the owner's household membership: assign the shared 'householdId' when the
147	        // request opts in and joins an existing household, and record the household size. This runs
148	        // before the identity-key check so that check sees the owner's final household id.
149	        applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
150	        // Reject the create when the owner's whole derived identity key (normalized telephone,
151	        // email and household id) already matches an existing owner. This single rule subsumes the
152	        // former separate telephone, email and household duplicate checks.
153	        rejectWhenIdentityInUse(owner);
154	        // Assign the remaining create-time derived fields (namesake count, customer code,
155	        // membership number and bulk-signup warning), each fixed at creation time.
156	        assignDerivedFields(owner);
157	        this.clinicService.saveOwner(owner);
158	        // Emit an audit line for the successful create, carrying the owner id, customer code and
159	        // registration date so the create can be traced from the dedicated AUDIT log.
160	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
161	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
162	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
163	        headers.setLocation(UriComponentsBuilder.newInstance()
164	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
165	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
166	    }
167	
168	    /**
169	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
170	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
171	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
172	     * the sequence of create-time rejections stays readable and a new rule is added as one more
173	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
174	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
175	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
176	     * the household id has been resolved, because that key includes the household id.
177	     *
178	     * @param owner the newly mapped and normalized owner being created
179	     */
180	    private void rejectDisallowedOwnerCreation(Owner owner) {
181	        rejectWhenDailyLimitReached(owner);
182	        rejectWhenCityAtCapacity(owner);
183	    }
184	
185	    /**
186	     * Applies the household-membership rules for a newly normalized owner being created. It finds
187	     * the existing owners who share the owner's household (same last name and address, compared
188	     * case-insensitively with collapsed whitespace), then, using that single lookup: when the
189	     * request opts in via {@code sharesHousehold} and the owner joins an existing household, assigns
190	     * the new owner and every existing member the same stable {@code householdId}; and records the
191	     * owner's {@code householdSize}. Sharing a household is no longer a rejection on its own: a new
192	     * owner is rejected only when its whole identity key matches an existing owner (see
193	     * {@link #rejectWhenIdentityInUse}), and the household id resolved here is part of that key.
194	     *
195	     * @param owner           the newly mapped and normalized owner being created
196	     * @param sharesHousehold whether the request opted in to joining an existing household
197	     */
198	    private void applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
199	        // Identify any existing owners who share a household (same last name and address,
200	        // compared case-insensitively with collapsed whitespace) with the owner being created.
201	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
202	        // When opting in and joining an existing household, assign the new owner and every
203	        // existing member the same stable household identifier derived from the last name and
204	        // address, so all owners of the household share one 'householdId'.
205	        if (sharesHousehold && !householdMembers.isEmpty()) {
206	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
207	            owner.setHouseholdId(householdId);
208	            for (Owner member : householdMembers) {
209	                if (!householdId.equals(member.getHouseholdId())) {
210	                    member.setHouseholdId(householdId);
211	                    this.clinicService.saveOwner(member);
212	                }
213	            }
214	        }
215	        // Record the size of this owner's household after this create, i.e. the number of owners
216	        // sharing this owner's 'householdId' once it is persisted. An owner that shares an existing
217	        // household counts the matched members plus itself; an owner without a shared household is a
218	        // household of one. Fixed at creation time.
219	        owner.setHouseholdSize(owner.getHouseholdId() == null ? 1 : householdMembers.size() + 1);
220	    }
221	
222	    /**
223	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
224	     * has already been resolved: the namesake count, the per-city customer code, the membership
225	     * number derived from that customer code and the registration year, and the bulk-signup warning
226	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
227	     * here keeps {@link #addOwner} focused on the high-level create sequence.
228	     *
229	     * @param owner the owner being created, already normalized and with its household resolved
230	     */
231	    private void assignDerivedFields(Owner owner) {
232	        // Record how many existing owners already share this owner's first and last name
233	        // (compared case-insensitively) before this create, fixed at creation time.
234	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
235	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
236	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
237	        // time.
238	        owner.setCustomerCode(customerCode(owner));
239	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
240	        // of the registration date's year (e.g. 'NSW-A1B2C3D4-M26'), fixed at creation time.
241	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
242	        // Flag the create when more than 80 owners have already been created on this owner's
243	        // (adjusted business-day) registration date, fixed at creation time.
244	        owner.setBulkSignupWarning(
245	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
246	    }
247	
248	    /**
249	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
250	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
251	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
252	     * the former separate telephone, email and household duplicate checks: two owners collide only
253	     * when their whole keys are equal, and members of one household with different telephones have
254	     * different keys and are both allowed.
255	     *
256	     * @param owner the owner being created, already normalized and with its household resolved
257	     */
258	    private void rejectWhenIdentityInUse(Owner owner) {
259	        String identityKey = owner.getIdentityKey();
260	        boolean inUse = this.clinicService.findAllOwners().stream()
261	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
262	        if (inUse) {
263	            throw new DuplicateIdentityException(
264	                "An owner with identity key " + identityKey + " already exists");
265	        }
266	    }
267	
268	    /**
269	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
270	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
271	     *
272	     * @param owner the owner being created
273	     */
274	    private void rejectWhenDailyLimitReached(Owner owner) {
275	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
276	            throw new DailyOwnerLimitExceededException(
277	                "The maximum number of owners that may be created today has already been reached");
278	        }
279	    }
280	
281	    /**
282	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
283	     * or more owners, with 409 Conflict.
284	     *
285	     * @param owner the owner being created
286	     */
287	    private void rejectWhenCityAtCapacity(Owner owner) {
288	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
289	            throw new CityCapacityExceededException(
290	                "The city " + owner.getCity() + " already contains the maximum number of owners");
291	        }
292	    }
293	
294	    /**
295	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
296	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
297	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
298	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
299	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
300	     * server's current date. Canonicalising the address here, before the household checks read it,
301	     * ensures duplicate detection and the shared household id both compare the normalized form.
302	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
303	     * duplicate, household and customer-code rules.
304	     *
305	     * @param owner the newly mapped owner to canonicalize
306	     */
307	    private void normalizeOwnerFields(Owner owner) {
308	        // Normalize the address on create so it is stored and returned in canonical form and every
309	        // later comparison (household duplicate detection and the shared household id) uses it.
310	        // A value that is blank after normalization is rejected with 400.
311	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
312	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
313	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
314	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
315	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
316	        // Store the (already syntactically validated) email lower-cased so it is persisted and
317	        // returned in canonical form. A missing email is left untouched.
318	        owner.setEmail(normalizeEmail(owner.getEmail()));
319	        // Validate the optional postcode against the fixed range for the city's region. A postcode
320	        // is checked only when present (it is optional); one out of range for the city's region is
321	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
322	        // value is left unchanged.
323	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
324	        // Default the registration date to the server's current date when the client did not
325	        // supply one, then roll the effective date forward to a business day so a Saturday or
326	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
327	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
328	        // date-derived field (such as the membership number's year segment) and the per-day
329	        // create-limit are computed from.
330	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
331	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
332	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
333	    }
334	
335	    /**
336	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
337	     * following Monday, while a weekday is returned unchanged. Applied to the effective
338	     * registration date (whether supplied in the request or defaulted to the server date) so the
339	     * persisted registration date, every value derived from it and the per-day create-limit all
340	     * use the adjusted business day.
341	     *
342	     * @param date the effective registration date
343	     * @return the same date if it is a weekday, otherwise the following Monday
344	     */
345	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
346	        java.time.LocalDate adjusted = date;
347	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
348	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
349	            adjusted = adjusted.plusDays(1);
350	        }
351	        return adjusted;
352	    }
353	
354	    /**
355	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
356	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
357	     * syntactically valid address (rejecting anything else with 400).
358	     *
359	     * @param email the email value (may be {@code null})
360	     * @return the lower-cased email, or {@code null} if the input was {@code null}
361	     */
362	    private String normalizeEmail(String email) {
363	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
364	    }
365	
366	    /**
367	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
368	     * region derived from the owner's postcode (falling back to the city, via
369	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
370	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
371	     * 'NSW-A1B2C3D4'). The identity carries no sequence number, so it is a pure function of the
372	     * owner's region and identity fields.
373	     *
374	     * @param owner the owner being created, already normalized
375	     * @return the formatted customer code
376	     */
377	    private String customerCode(Owner owner) {
378	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
379	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
380	        return region + "-" + hash8;
381	    }
382	
383	    /**
384	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
385	     * fix the per-city sequence of an owner's customer code at creation time.
386	     *
387	     * @param city the city of the owner being created
388	     * @return the number of existing owners in a matching city
389	     */
390	    private int countOwnersInCity(String city) {
391	        return (int) this.clinicService.findAllOwners().stream()
392	            .filter(existing -> existing.getCity() != null
393	                && existing.getCity().equalsIgnoreCase(city))
394	            .count();
395	    }
396	
397	    /**
398	     * Counts the existing owners whose registration date is the given adjusted business day. Used
399	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
400	     * owners already carry that business day as their registration date.
401	     *
402	     * @param date the adjusted business-day registration date to match
403	     * @return the number of existing owners registered on that date
404	     */
405	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
406	        return (int) this.clinicService.findAllOwners().stream()
407	            .filter(existing -> date.equals(existing.getRegistrationDate()))
408	            .count();
409	    }
410	
411	    /**
412	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
413	     * the last two digits of the registration date's year (e.g. 'NSW-A1B2C3D4-M26').
414	     *
415	     * @param customerCode     the owner's customer code
416	     * @param registrationDate the owner's registration date
417	     * @return the formatted membership number
418	     */
419	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
420	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
421	    }
422	
423	    /**
424	     * Returns the existing owners who share the given household, i.e. have the same last name and
425	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
426	     * differing only in letter case or in incidental whitespace are treated as the same household.
427	     *
428	     * @param lastName the last name of the owner being created
429	     * @param address  the address of the owner being created
430	     * @return the existing owners with a matching last name and address (possibly empty)
431	     */
432	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
433	        String householdKey = householdNormalizer.householdKey(lastName, address);
434	        return this.clinicService.findAllOwners().stream()
435	            .filter(existing -> householdNormalizer
436	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
437	            .toList();
438	    }
439	
440	    /**
441	     * Counts the existing owners who share the given first and last name, compared
442	     * case-insensitively. Used to fix an owner's namesake count at creation time.
443	     *
444	     * @param firstName the first name of the owner being created
445	     * @param lastName  the last name of the owner being created
446	     * @return the number of existing owners with a matching first and last name
447	     */
448	    private int countNamesakes(String firstName, String lastName) {
449	        return (int) this.clinicService.findAllOwners().stream()
450	            .filter(existing -> existing.getFirstName() != null
451	                && existing.getFirstName().equalsIgnoreCase(firstName)
452	                && existing.getLastName() != null
453	                && existing.getLastName().equalsIgnoreCase(lastName))
454	            .count();
455	    }
456	
457	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
458	    @Override
459	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
460	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
461	        if (currentOwner == null) {
462	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
463	        }
464	        currentOwner.setAddress(ownerFieldsDto.getAddress());
465	        currentOwner.setCity(ownerFieldsDto.getCity());
466	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
467	        currentOwner.setLastName(ownerFieldsDto.getLastName());
468	        // Normalize the telephone to canonical E.164 form so it is stored and returned
469	        // consistently with create; an unformattable value is rejected with 400.
470	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
471	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
472	        this.clinicService.saveOwner(currentOwner);
473	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
474	    }
475	
476	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
477	    @Transactional
478	    @Override
479	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
480	        Owner owner = this.clinicService.findOwnerById(ownerId);
481	        if (owner == null) {
482	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
483	        }
484	        this.clinicService.deleteOwner(owner);
485	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
486	    }
487	
488	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
489	    @Override
490	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
491	        Owner owner = this.clinicService.findOwnerById(ownerId);
492	        if (owner == null) {
493	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
494	        }
495	        HttpHeaders headers = new HttpHeaders();
496	        Pet pet = petMapper.toPet(petFieldsDto);
497	        owner.setId(ownerId);
498	        pet.setOwner(owner);
499	        pet.getType().setName(null);
500	        this.clinicService.savePet(pet);
501	        PetDto petDto = petMapper.toPetDto(pet);
502	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
503	            .buildAndExpand(pet.getId()).toUri());
504	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
505	    }
506	
507	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
508	    @Override
509	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
510	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
511	        if (currentOwner != null) {
512	            Pet currentPet = this.clinicService.findPetById(petId);
513	            if (currentPet != null) {
514	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
515	                currentPet.setName(petFieldsDto.getName());
516	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
517	                this.clinicService.savePet(currentPet);
518	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
519	            }
520	        }
521	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
522	    }
523	
524	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
525	    @Override
526	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
527	        HttpHeaders headers = new HttpHeaders();
528	        Visit visit = visitMapper.toVisit(visitFieldsDto);
529	        Pet pet = new Pet();
530	        pet.setId(petId);
531	        visit.setPet(pet);
532	        this.clinicService.saveVisit(visit);
533	        VisitDto visitDto = visitMapper.toVisitDto(visit);
534	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
535	            .buildAndExpand(visit.getId()).toUri());
536	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
537	    }
538	
539	
540	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
541	    @Override
542	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
543	        Owner owner = this.clinicService.findOwnerById(ownerId);
544	        if (owner != null) {
545	            Pet pet = owner.getPet(petId);
546	            if (pet != null) {
547	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
548	            }
549	        }
550	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
551	    }
552	}
